import { Component, EventEmitter, OnInit, Output } from '@angular/core';
import { UploadService } from '../../../services/upload/upload.service';
import { FileSelectionService } from '../../../services/upload/file-selection/file-selection.service';
import { NgxFileDropEntry, NgxFileDropModule } from 'ngx-file-drop';
import { FileStorageService } from '../../../services/upload/file-storage/file-storage.service';
import { selectedfileMDL } from '../../../interfaces/upload.interface';


@Component({
  selector: 'uploadfile',
  standalone: true,
  imports: [NgxFileDropModule],
  templateUrl: './uploadfile.component.html',
  styleUrls: ['./uploadfile.component.scss']
})
export class uploadfileComponent implements OnInit {
  isDragging: boolean = false;
  @Output() dataRecieved = new EventEmitter<any>();
  constructor(public us: UploadService, private selection: FileSelectionService, private store: FileStorageService) { }

  ngOnInit(): void {
  }

  async onFileDrop(event: NgxFileDropEntry[]) {
    this.isDragging = true;
    let listData: selectedfileMDL[] = await this.selection.fetchFiles(event);
    this.isDragging = false;
    // console.log('listData', JSON.stringify(listData));
    if (listData.length) {
      this.store.setSelectedFileStorage(listData)
      this.dataRecieved.emit('DATA-RECIEVED');
    }
  }

  DragTo(e){
  }


}
